// Транспорт навмисно нічого не знає про домен — лише «подія +
// повідомлення» і реконект. Доменні підписки живуть у самих сутностях.
const INITIAL_RECONNECT_DELAY_MS = 1000;
const MAX_RECONNECT_DELAY_MS = 30000;
// Зʼєднання вважається робочим, лише коли протрималося стільки. Сервер, що
// приймає й одразу рве зʼєднання, інакше давав вічний цикл «відкрилось —
// закрилось» раз на секунду зі штормом сповіщень на кожному колі.
const STABLE_CONNECTION_MS = 5000;
class WebsocketTransport {
    constructor() {
        // Номер поточної спроби: відповідь функції адреси, що прийшла після
        // disconnect() чи нової спроби, вже нічого не відкриває.
        this.generation = 0;
        this.status = 'idle';
        this.intentionalDisconnect = false;
        this.reconnectDelay = INITIAL_RECONNECT_DELAY_MS;
        // Що вже сказано слухачам: «зʼєднання є» і чи повідомлено про помилку в
        // поточному збої. Сповіщення — по одному на обрив, а не на кожну спробу.
        this.announcedUp = false;
        this.everAnnouncedUp = false;
        this.errorReported = false;
        this.sendQueue = [];
        this.eventHandlers = new Map();
        this.openHandlers = new Set();
        this.closeHandlers = new Set();
        this.errorHandlers = new Set();
    }
    connect(source) {
        if (this.socket || this.status !== 'idle') {
            this.disconnect();
        }
        this.source = source;
        this.intentionalDisconnect = false;
        this.reconnectDelay = INITIAL_RECONNECT_DELAY_MS;
        this.openConnection();
    }
    // Свідоме відключення не має породжувати реконект, інакше транспорт
    // ломився б на сервер після явного прохання закрити зʼєднання.
    disconnect() {
        this.intentionalDisconnect = true;
        this.generation += 1;
        clearTimeout(this.reconnectTimer);
        this.reconnectTimer = undefined;
        clearTimeout(this.stableTimer);
        this.stableTimer = undefined;
        this.announcedUp = false;
        this.everAnnouncedUp = false;
        this.errorReported = false;
        this.sendQueue = [];
        this.socket?.close();
        this.socket = undefined;
        this.setStatus('idle');
    }
    send(event, message) {
        if (this.socket && this.socket.readyState === WebSocket.OPEN) {
            this.socket.send(JSON.stringify({ event, message }));
            return;
        }
        this.sendQueue.push({ event, message });
    }
    on(event, handler) {
        if (!this.eventHandlers.has(event)) {
            this.eventHandlers.set(event, new Set());
        }
        this.eventHandlers.get(event)?.add(handler);
        return () => {
            this.eventHandlers.get(event)?.delete(handler);
        };
    }
    onOpen(handler) {
        this.openHandlers.add(handler);
        return () => {
            this.openHandlers.delete(handler);
        };
    }
    onClose(handler) {
        this.closeHandlers.add(handler);
        return () => {
            this.closeHandlers.delete(handler);
        };
    }
    onError(handler) {
        this.errorHandlers.add(handler);
        return () => {
            this.errorHandlers.delete(handler);
        };
    }
    openConnection() {
        const source = this.source;
        if (!source)
            return;
        this.setStatus('connecting');
        if (typeof source === 'string') {
            this.openSocket(source);
            return;
        }
        const generation = ++this.generation;
        source().then((url) => {
            if (generation !== this.generation || this.intentionalDisconnect)
                return;
            this.openSocket(url);
        }, () => {
            if (generation !== this.generation || this.intentionalDisconnect)
                return;
            // Адресу не отримали (токен не видали, мережа) — це невдала спроба,
            // як і відхилене зʼєднання: помилка й реконект із паузою.
            this.reportError();
            this.setStatus('disconnected');
            this.scheduleReconnect();
        });
    }
    openSocket(url) {
        const ws = new WebSocket(url);
        ws.onopen = () => {
            this.flushSendQueue();
            this.setStatus('connected');
            // Перше зʼєднання оголошуємо одразу; після обриву — лише коли
            // протрималося, інакше мигання давало б «підключено» на кожному колі.
            if (!this.everAnnouncedUp)
                this.announceUp();
            clearTimeout(this.stableTimer);
            this.stableTimer = setTimeout(() => {
                this.reconnectDelay = INITIAL_RECONNECT_DELAY_MS;
                this.announceUp();
            }, STABLE_CONNECTION_MS);
        };
        ws.onmessage = (event) => {
            this.receiveMessage(String(event.data));
        };
        ws.onerror = () => {
            this.reportError();
        };
        ws.onclose = () => {
            this.socket = undefined;
            clearTimeout(this.stableTimer);
            this.stableTimer = undefined;
            this.setStatus('disconnected');
            if (!this.intentionalDisconnect) {
                this.scheduleReconnect();
            }
        };
        this.socket = ws;
    }
    setStatus(next) {
        const previous = this.status;
        if (previous === next)
            return;
        this.status = next;
        // «Зʼєднання втрачено» — один раз на обрив: наступні невдалі спроби
        // вже нічого не оголошують, доки зʼєднання не стане стабільним.
        if (next === 'disconnected' && previous === 'connected' && this.announcedUp) {
            this.announcedUp = false;
            this.closeHandlers.forEach((handler) => handler());
        }
    }
    announceUp() {
        if (this.announcedUp)
            return;
        this.announcedUp = true;
        this.everAnnouncedUp = true;
        this.errorReported = false;
        this.openHandlers.forEach((handler) => handler());
    }
    // Одна помилка на збій: кожна наступна спроба реконекту теж закінчується
    // onerror, і без цього сервер, що лежить, давав сповіщення на кожну.
    reportError() {
        if (this.errorReported)
            return;
        this.errorReported = true;
        this.errorHandlers.forEach((handler) => handler());
    }
    scheduleReconnect() {
        clearTimeout(this.reconnectTimer);
        this.reconnectTimer = setTimeout(() => {
            this.openConnection();
        }, this.reconnectDelay);
        this.reconnectDelay = Math.min(this.reconnectDelay * 2, MAX_RECONNECT_DELAY_MS);
    }
    flushSendQueue() {
        const queued = this.sendQueue;
        this.sendQueue = [];
        queued.forEach(({ event, message }) => {
            this.socket?.send(JSON.stringify({ event, message }));
        });
    }
    receiveMessage(raw) {
        let parsed;
        try {
            parsed = JSON.parse(raw);
        }
        catch {
            this.reportError();
            return;
        }
        if (!parsed.event)
            return;
        this.eventHandlers.get(parsed.event)?.forEach((handler) => handler(parsed.message));
    }
}
export const websocketTransport = new WebsocketTransport();
